# OAuth State	GitHub Access Token
# Generated by your application	Issued by GitHub
# Used to protect OAuth flow	Used to access GitHub APIs
# Generated by create_oauth_state()	Received through exchange_code(code)
# Verified by verify_oauth_state()
import hashlib

# HMAC is a message authentication mechanism that uses a secret key and a hash algorithm to verify data integrity and authenticity.
import hmac
import secrets
import time
from app.core.config import settings

def create_oauth_state(user_id: int) -> str:
    issued = str(int(time.time()))
    nonce = secrets.token_urlsafe(24)
    payload = f"{user_id}:{issued}:{nonce}"
    signature = hmac.new(settings.GITHUB_OAUTH_STATE_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return f"{payload}:{signature}"

def verify_oauth_state(state: str) -> int:
    try:
        user_id, issued, nonce, signature = state.split(":", 3)
        payload = f"{user_id}:{issued}:{nonce}"
        expected = hmac.new(settings.GITHUB_OAUTH_STATE_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
        # To compare signatures in a timing-resistant way.
        if not hmac.compare_digest(signature, expected):
            raise ValueError
        age = int(time.time()) - int(issued)
        if age < 0 or age > 600:
            raise ValueError
        return int(user_id)
    except Exception as exc:
        raise ValueError("Invalid or expired OAuth state") from exc
